window.PRINCIPLES=[{"title":"Steady, values-led decisions","summary":"Bring consistency to leadership and use Aggie values to guide decisions.","practice":"Explain the values and reasoning behind an important decision."},{"title":"A supportive workplace","summary":"Build a culture where people feel respected and supported.","practice":"Ask a colleague what support would help them do their best work."},{"title":"Effort and excellence","summary":"Put sustained effort into work that meets high standards.","practice":"Agree on what a good result looks like before work starts."},{"title":"Clarity and accountability","summary":"Make expectations understandable and follow through on commitments.","practice":"Close a meeting with a named owner, next step and check-in."},{"title":"Growth for others","summary":"Invest in the development of the people around you.","practice":"Create space for an employee to practice a new skill."},{"title":"Working as one university","summary":"Connect efforts across A&M and the System around shared goals.","practice":"Invite a partner unit into planning before a decision is final."},{"title":"Simpler ways to work","summary":"Remove obstacles that make useful work harder.","practice":"Identify one unnecessary handoff and work with its owner to improve it."},{"title":"Communication before surprises","summary":"Share relevant information early so people can prepare.","practice":"Raise a risk early and explain the action being taken."},{"title":"Thoughtful stewardship","summary":"Use time, funds and other resources with care.","practice":"Check the effort and value of a recurring meeting or process."},{"title":"Ownership and learning","summary":"Acknowledge errors, accept responsibility and apply the lessons.","practice":"Discuss what to change after a setback without assigning blame."},{"title":"Responding to change","summary":"Stay flexible as needs and circumstances evolve.","practice":"Ask what has changed and adjust a plan with the people affected."},{"title":"Improvement and new ideas","summary":"Keep looking for better approaches and useful innovations.","practice":"Try a small change, review its results and share what you learn."}];
